30	func newMigrateCmd() *cobra.Command {
31		var checkpointsFlag string
32		var forceFlag bool
33	
34		cmd := &cobra.Command{
35			Use:    "migrate",
36			Short:  "Migrate Entire data to newer formats",
37			Long:   `Migrate Entire data to newer formats. Currently supports migrating v1 checkpoints to v2.`,
38			Hidden: true,
39			RunE: func(cmd *cobra.Command, _ []string) error {
40				if checkpointsFlag == "" {
41					return cmd.Help()
42				}
43				if checkpointsFlag != "v2" {
44					return fmt.Errorf("unsupported checkpoints version: %q (only \"v2\" is supported)", checkpointsFlag)
45				}
46	
47				ctx := cmd.Context()
48	
49				if _, err := paths.WorktreeRoot(ctx); err != nil {
50					cmd.SilenceUsage = true
51					fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
52					return NewSilentError(errors.New("not a git repository"))
53				}
54	
55				logging.SetLogLevelGetter(GetLogLevel)
56				if initErr := logging.Init(ctx, ""); initErr != nil {
57					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not initialize logging: %v\n", initErr)
58				} else {
59					defer logging.Close()
60				}
61				return runMigrateCheckpointsV2(ctx, cmd, forceFlag)
62			},
63		}
64	
65		cmd.Flags().StringVar(&checkpointsFlag, "checkpoints", "", "Target checkpoint format version (e.g., \"v2\")")
66		cmd.Flags().BoolVar(&forceFlag, "force", false, "Force re-migration of all checkpoints, overwriting existing v2 data")
67	
68		return cmd
69	}
