134	func printMigrateCompletion(out io.Writer, result *migrateResult) {
135		if result.total == 0 {
136			fmt.Fprintln(out, "Nothing to migrate: no v1 checkpoints found")
137			fmt.Fprintln(out)
138			return
139		}
140	
141		fmt.Fprintf(out, "Migration complete: %d migrated, %d skipped, %d failed\n",
142			result.migrated, result.skipped, result.failed)
143	
144		if result.hasLoggedDetails() {
145			fmt.Fprintf(out, "Details for skipped, missing, incomplete, or failed checkpoints were logged to %s.\n", migrationLogFile)
146		}
147	
148		fmt.Fprintln(out)
149	}
