155	func printV2GenerationRepairResult(out, errOut io.Writer, result *strategy.RepairV2GenerationMetadataResult) {
156		if result == nil {
157			return
158		}
159	
160		for _, warning := range result.Warnings {
161			fmt.Fprintf(errOut, "Warning: %s\n", warning)
162		}
163	
164		if len(result.Repaired) == 0 && len(result.Failed) == 0 {
165			return
166		}
167	
168		fmt.Fprintf(out, "Archived generation metadata repair: %d repaired, %d skipped, %d failed\n",
169			len(result.Repaired), len(result.Skipped), len(result.Failed))
170	}
