197	// migrateCheckpointsV2 returns the /full/<n> refs the packer wrote so callers
198	// can pass them as exclusions to the generation-metadata repair pass.
199	func migrateCheckpointsV2(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, progressOut io.Writer, force bool) (*migrateResult, []plumbing.ReferenceName, error) {
200		v1List, err := v1Store.ListCommitted(ctx)
201		if err != nil {
202			return nil, nil, fmt.Errorf("failed to list v1 checkpoints: %w", err)
203		}
204	
205		if len(v1List) == 0 {
206			return &migrateResult{}, nil, nil
207		}
208	
209		sortMigratableCheckpoints(v1List)
210		total := len(v1List)
211		result := &migrateResult{total: total}
212		progress := startProgressBar(progressOut, "Migrating checkpoints", total)
213		defer progress.Finish()
214	
215		_, fullCurrentRefErr := repo.Reference(plumbing.ReferenceName(paths.V2FullCurrentRefName), true)
216		fullCurrentExistsBefore := fullCurrentRefErr == nil
217	
218		// One up-front tree walk to make per-session "are /full/* artifacts
219		// present?" checks O(1) inside the migration loop.
220		fullArtifactsIndex, err := v2Store.BuildFullSessionArtifactsIndex()
221		if err != nil {
222			return nil, nil, fmt.Errorf("build v2 /full/* presence index: %w", err)
223		}
224	
225		packer := newGenerationPacker(repo, v2Store)
226	
227		for _, info := range v1List {
228			fullCheckpoint, outcome, migrateErr := migrateOneCheckpoint(ctx, repo, v1Store, v2Store, info, force, fullArtifactsIndex)
229			result.missingSessions += outcome.missingSessions
230			if outcome.compactTranscriptSkipped {
231				result.compactTranscriptSkipped++
232			}
233	
234			if migrateErr != nil {
235				switch {
236				case errors.Is(migrateErr, errAlreadyMigrated):
237					logCheckpointMigrationSkip(ctx, info.CheckpointID, "already in v2", migrateErr)
238					result.skipped++
239				case errors.Is(migrateErr, errNoMigratableSessions):
240					logCheckpointMigrationSkip(ctx, info.CheckpointID, "no migratable v1 sessions", migrateErr)
241					result.skipped++
242				default:
243					logging.Error(ctx, "checkpoint migration failed",
244						slog.String("checkpoint_id", string(info.CheckpointID)),
245						slog.String("error", migrateErr.Error()),
246					)
247					result.failed++
248				}
249				progress.Increment()
250				continue
251			}
252	
253			if fullCheckpoint != nil {
254				if packErr := packer.add(ctx, *fullCheckpoint); packErr != nil {
255					return result, packer.writtenRefs, fmt.Errorf("failed to pack migrated raw transcripts: %w", packErr)
256				}
257			}
258			result.migrated++
259			progress.Increment()
260		}
261	
262		progress.Finish()
263		stopFinalize := startSpinner(progressOut, "Packing migrated raw transcripts")
264		if err := packer.finalize(ctx, !fullCurrentExistsBefore); err != nil {
265			stopFinalize(false)
266			return result, packer.writtenRefs, fmt.Errorf("failed to pack migrated raw transcripts: %w", err)
267		}
268		stopFinalize(true)
269	
270		return result, packer.writtenRefs, nil
271	}
