273	func logCheckpointMigrationSkip(ctx context.Context, checkpointID id.CheckpointID, reason string, err error) {
274		logging.Info(ctx, "checkpoint migration skipped",
275			slog.String("checkpoint_id", string(checkpointID)),
276			slog.String("reason", reason),
277			slog.String("error", err.Error()),
278		)
279	}
