281	func sortMigratableCheckpoints(checkpoints []checkpoint.CommittedInfo) {
282		sort.SliceStable(checkpoints, func(i, j int) bool {
283			left := checkpoints[i].CreatedAt
284			right := checkpoints[j].CreatedAt
285			switch {
286			case left.IsZero() && right.IsZero():
287				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
288			case left.IsZero():
289				return false
290			case right.IsZero():
291				return true
292			case left.Equal(right):
293				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
294			default:
295				return left.Before(right)
296			}
297		})
298	}
