300	type migrateCheckpointOutcome struct {
301		missingSessions          int
302		compactTranscriptSkipped bool
303	}
304	
305	func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, force bool, fullArtifacts checkpoint.FullSessionArtifactsIndex) (*migratedFullCheckpoint, migrateCheckpointOutcome, error) {
306		var outcome migrateCheckpointOutcome
307	
308		existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
309		if err != nil {
310			return nil, outcome, fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
311		}
312	
313		if existing != nil && !force {
314			// Already in v2. Pack sessions whose /full/* artifacts are missing
315			// (resume an interrupted run) and backfill transcript.jsonl on /main
316			// where it's missing. With nothing to do on either front, return
317			// errAlreadyMigrated so the caller counts it as skipped.
318			fullCheckpoint, err := collectMissingFullCheckpointForPacking(ctx, repo, v1Store, v2Store, info, existing, fullArtifacts)
319			if err != nil && !errors.Is(err, errAlreadyMigrated) {
320				return nil, outcome, err
321			}
322			backfilled, backfillErr := backfillCompactTranscripts(ctx, v1Store, v2Store, info, existing)
323			if errors.Is(backfillErr, errTranscriptNotGeneratable) {
324				outcome.compactTranscriptSkipped = true
325			} else if backfillErr != nil && !errors.Is(backfillErr, errAlreadyMigrated) {
326				return nil, outcome, backfillErr
327			}
328			if fullCheckpoint == nil {
329				if backfilled > 0 {
330					return nil, outcome, nil
331				}
332				return nil, outcome, errAlreadyMigrated
333			}
334			return fullCheckpoint, outcome, nil
335		}
336	
337		if existing != nil && force {
338			if pruneErr := pruneV2CheckpointForForce(ctx, repo, v2Store, info.CheckpointID); pruneErr != nil {
339				return nil, outcome, fmt.Errorf("failed to reset existing v2 checkpoint %s before force migration: %w", info.CheckpointID, pruneErr)
340			}
341		}
342	
343		summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
344		if err != nil {
345			return nil, outcome, fmt.Errorf("failed to read v1 summary: %w", err)
346		}
347		if summary == nil {
348			return nil, outcome, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
349		}
350	
351		compactFailed := false
352		shouldCopyTaskMetadata := false
353		skippedMissingSessions := 0
354		migratedSessions := 0
355		v1ToV2SessionIdx := make(map[int]int, len(summary.Sessions))
356		fullCheckpoint := &migratedFullCheckpoint{
357			checkpointID: info.CheckpointID,
358		}
359	
360		for sessionIdx := range len(summary.Sessions) {
361			content, skipped, readErr := readV1SessionForMigration(ctx, v1Store, info.CheckpointID, sessionIdx)
362			if skipped {
363				skippedMissingSessions++
364				outcome.missingSessions++
365				continue
366			}
367			if readErr != nil {
368				return nil, outcome, fmt.Errorf("failed to read v1 session %d: %w", sessionIdx, readErr)
369			}
370			if content.Metadata.IsTask {
371				shouldCopyTaskMetadata = true
372			}
373	
374			opts := buildMigrateWriteOpts(content, info, summary.CombinedAttribution)
375	
376			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
377			if compacted != nil {
378				opts.CompactTranscript = compacted
379				opts.CompactTranscriptStart = computeCompactOffset(ctx, content.Transcript, compacted, content.Metadata)
380			} else if len(content.Transcript) > 0 {
381				compactFailed = true
382			}
383	
384			mainOpts := opts
385			mainOpts.Transcript = redact.AlreadyRedacted(nil)
386			v2SessionIdx, writeErr := v2Store.WriteCommittedWithSessionIndex(ctx, mainOpts)
387			if writeErr != nil {
388				return nil, outcome, fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
389			}
390			v1ToV2SessionIdx[sessionIdx] = v2SessionIdx
391			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
392				sessionIndex: v2SessionIdx,
393				content:      content,
394			})
395			migratedSessions++
396		}
397	
398		if migratedSessions == 0 {
399			return nil, outcome, fmt.Errorf("%w: v1 metadata lists %d session(s), but no transcript/session content exists for any of them", errNoMigratableSessions, len(summary.Sessions))
400		}
401	
402		if shouldCopyTaskMetadata {
403			taskTrees, taskErr := collectTaskMetadataForMigratedFullGeneration(repo, info.CheckpointID, summary, v1ToV2SessionIdx)
404			if taskErr != nil {
405				logging.Warn(ctx, "failed to copy task metadata to v2",
406					slog.String("checkpoint_id", string(info.CheckpointID)),
407					slog.String("error", taskErr.Error()),
408				)
409			} else {
410				fullCheckpoint.taskTrees = taskTrees
411			}
412		}
413	
414		if compactFailed {
415			outcome.compactTranscriptSkipped = true
416			logging.Warn(ctx, "compact transcript not generated during checkpoint migration",
417				slog.String("checkpoint_id", string(info.CheckpointID)),
418				slog.Int("migrated_sessions", migratedSessions),
419			)
420		}
421		if skippedMissingSessions > 0 {
422			logging.Warn(ctx, "checkpoint migration skipped v1 sessions with missing transcript/session content",
423				slog.String("checkpoint_id", string(info.CheckpointID)),
424				slog.Int("missing_sessions", skippedMissingSessions),
425			)
426		}
427	
428		return fullCheckpoint, outcome, nil
429	}
