431	// generationPacker buffers up to batchSize migrated checkpoints and flushes
432	// them into a single archived /full/<n> ref each time the buffer fills, so
433	// peak heap stays bounded by one batch worth of transcripts instead of
434	// growing with the total v1 list. The next generation number is resolved
435	// lazily on first flush so force-migration prune steps that remove existing
436	// archived refs are visible before we pick the next slot.
437	type generationPacker struct {
438		repo           *git.Repository
439		v2Store        *checkpoint.V2GitStore
440		batchSize      int
441		nextGeneration int
442		numbered       bool
443		pending        []migratedFullCheckpoint
444		flushed        bool
445		// writtenRefs records every /full/<n> ref this packer creates so the
446		// caller can exclude them from the generation-metadata repair pass.
447		writtenRefs []plumbing.ReferenceName
448	}
449	
450	func newGenerationPacker(repo *git.Repository, v2Store *checkpoint.V2GitStore) *generationPacker {
451		batchSize := migrateMaxCheckpointsPerGeneration
452		if batchSize <= 0 {
453			batchSize = checkpoint.DefaultMaxCheckpointsPerGeneration
454		}
455		return &generationPacker{
456			repo:      repo,
457			v2Store:   v2Store,
458			batchSize: batchSize,
459		}
460	}
461	
462	func (p *generationPacker) add(ctx context.Context, cp migratedFullCheckpoint) error {
463		p.pending = append(p.pending, cp)
464		if len(p.pending) >= p.batchSize {
465			return p.flush(ctx)
466		}
467		return nil
468	}
469	
470	func (p *generationPacker) flush(ctx context.Context) error {
471		if len(p.pending) == 0 {
472			return nil
473		}
474		if !p.numbered {
475			next, err := p.v2Store.NextGenerationNumber()
476			if err != nil {
477				return fmt.Errorf("list archived v2 generations: %w", err)
478			}
479			p.nextGeneration = next
480			p.numbered = true
481		}
482		refName := plumbing.ReferenceName(fmt.Sprintf("%s%013d", paths.V2FullRefPrefix, p.nextGeneration))
483		if err := writeMigratedFullGeneration(ctx, p.repo, refName, p.pending); err != nil {
484			return err
485		}
486		p.writtenRefs = append(p.writtenRefs, refName)
487		p.nextGeneration++
488		p.pending = nil
489		p.flushed = true
490		return nil
491	}
492	
493	func (p *generationPacker) finalize(ctx context.Context, ensureEmptyCurrent bool) error {
494		if err := p.flush(ctx); err != nil {
495			return err
496		}
497		if p.flushed && ensureEmptyCurrent {
498			return ensureEmptyV2FullCurrent(ctx, p.repo)
499		}
500		return nil
501	}
502	
503	func writeMigratedFullGeneration(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, checkpoints []migratedFullCheckpoint) error {
504		entries := make(map[string]object.TreeEntry)
505	
506		for _, cp := range checkpoints {
507			for _, session := range cp.sessions {
508				if err := writeMigratedFullSessionEntries(ctx, repo, cp, session, entries); err != nil {
509					return fmt.Errorf("write full session entries for checkpoint %s session %d: %w", cp.checkpointID, session.sessionIndex, err)
510				}
511			}
512		}
513	
514		treeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
515		if err != nil {
516			return fmt.Errorf("build migrated generation tree: %w", err)
517		}
518	
519		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
520		// Reuse the transcripts already in memory rather than walking the tree
521		// we just built — same first/last-event range, no redundant blob reads.
522		gen, found := checkpoint.AggregateTranscriptTimestamps(migratedTranscripts(checkpoints))
523		if !found {
524			var err error
525			gen, found, err = v2Store.ComputeGenerationCheckpointTimestamps(treeHash)
526			if err != nil {
527				return fmt.Errorf("compute checkpoint timestamps: %w", err)
528			}
529		}
530		if !found {
531			gen, found = generationMetadataFromMigratedSessions(checkpoints)
532		}
533		if !found {
534			return fmt.Errorf("no timestamps found for migrated generation %s", refName)
535		}
536	
537		treeHash, err = v2Store.AddGenerationJSONToTree(treeHash, gen)
538		if err != nil {
539			return fmt.Errorf("add generation metadata: %w", err)
540		}
541	
542		commitHash, err := checkpoint.CreateCommit(ctx, repo, treeHash, plumbing.ZeroHash,
543			fmt.Sprintf("Archive migrated generation: %s\n", refName),
544			migrateAuthorName, migrateAuthorEmail)
545		if err != nil {
546			return fmt.Errorf("create migrated generation commit: %w", err)
547		}
548	
549		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
550			return fmt.Errorf("update migrated generation ref %s: %w", refName, err)
551		}
552		return nil
553	}
554	
555	func migratedTranscripts(checkpoints []migratedFullCheckpoint) [][]byte {
556		var transcripts [][]byte
557		for _, cp := range checkpoints {
558			for _, session := range cp.sessions {
559				if len(session.content.Transcript) == 0 {
560					continue
561				}
562				transcripts = append(transcripts, session.content.Transcript)
563			}
564		}
565		return transcripts
566	}
567	
568	func generationMetadataFromMigratedSessions(checkpoints []migratedFullCheckpoint) (checkpoint.GenerationMetadata, bool) {
569		var gen checkpoint.GenerationMetadata
570		found := false
571		for _, cp := range checkpoints {
572			for _, session := range cp.sessions {
573				checkpoint.MergeGenerationTime(&gen, &found, session.content.Metadata.CreatedAt)
574			}
575		}
576		return gen, found
577	}
