579	func writeMigratedFullSessionEntries(ctx context.Context, repo *git.Repository, cp migratedFullCheckpoint, session migratedFullSession, entries map[string]object.TreeEntry) error {
580		sessionPath := fmt.Sprintf("%s/%d/", cp.checkpointID.Path(), session.sessionIndex)
581		transcript := session.content.Transcript
582	
583		chunks, err := agent.ChunkTranscript(ctx, transcript, session.content.Metadata.Agent)
584		if err != nil {
585			return fmt.Errorf("chunk transcript: %w", err)
586		}
587		for i, chunk := range chunks {
588			blobHash, blobErr := checkpoint.CreateBlobFromContent(repo, chunk)
589			if blobErr != nil {
590				return fmt.Errorf("create transcript blob: %w", blobErr)
591			}
592			path := sessionPath + agent.ChunkFileName(paths.V2RawTranscriptFileName, i)
593			entries[path] = object.TreeEntry{
594				Name: path,
595				Mode: filemode.Regular,
596				Hash: blobHash,
597			}
598		}
599	
600		hashPath := sessionPath + paths.V2RawTranscriptHashFileName
601		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
602		hashBlob, err := checkpoint.CreateBlobFromContent(repo, []byte(contentHash))
603		if err != nil {
604			return fmt.Errorf("create transcript hash blob: %w", err)
605		}
606		entries[hashPath] = object.TreeEntry{
607			Name: hashPath,
608			Mode: filemode.Regular,
609			Hash: hashBlob,
610		}
611	
612		for _, taskTreeHash := range cp.taskTrees[session.sessionIndex] {
613			taskTree, treeErr := repo.TreeObject(taskTreeHash)
614			if treeErr != nil {
615				return fmt.Errorf("read task metadata tree: %w", treeErr)
616			}
617			taskEntries := make(map[string]object.TreeEntry)
618			if flattenErr := checkpoint.FlattenTree(repo, taskTree, sessionPath+"tasks", taskEntries); flattenErr != nil {
619				return fmt.Errorf("flatten task metadata tree: %w", flattenErr)
620			}
621			for path, entry := range taskEntries {
622				if _, exists := entries[path]; exists {
623					continue
624				}
625				entries[path] = entry
626			}
627		}
628	
629		return nil
630	}
