676	func pruneV2CheckpointForForce(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID) error {
677		for _, refName := range []plumbing.ReferenceName{
678			plumbing.ReferenceName(paths.V2MainRefName),
679			plumbing.ReferenceName(paths.V2FullCurrentRefName),
680		} {
681			if err := pruneV2CheckpointRef(ctx, repo, v2Store, refName, cpID); err != nil {
682				return err
683			}
684		}
685	
686		archived, err := v2Store.ListArchivedGenerations()
687		if err != nil {
