691			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + generation)
692			if err := pruneV2ArchivedCheckpointRef(ctx, repo, v2Store, refName, cpID); err != nil {
693				return err
694			}
695		}
696	
697		return nil
698	}
