700	func pruneV2CheckpointRef(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, refName plumbing.ReferenceName, cpID id.CheckpointID) error {
701		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
702		if err != nil {
703			if errors.Is(err, plumbing.ErrReferenceNotFound) {
704				return nil
705			}
706			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
707		}
708	
709		rootTree, err := repo.TreeObject(rootTreeHash)
710		if err != nil {
711			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
712		}
713		if _, err := rootTree.Tree(cpID.Path()); err != nil {
714			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
715		}
716	
717		shardPrefix := string(cpID[:2])
718		shardSuffix := string(cpID[2:])
719		newRoot, err := pruneCheckpointFromRoot(repo, rootTreeHash, shardPrefix, shardSuffix)
720		if err != nil {
721			return fmt.Errorf("failed to remove checkpoint subtree from %s: %w", refName, err)
722		}
723		if newRoot == rootTreeHash {
724			return nil
725		}
726	
727		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
728			fmt.Sprintf("Reset checkpoint before force migration: %s\n", cpID),
729			migrateAuthorName, migrateAuthorEmail)
730		if err != nil {
731			return fmt.Errorf("failed to create v2 prune commit for %s: %w", refName, err)
732		}
733	
734		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
735			return fmt.Errorf("failed to update ref %s: %w", refName, err)
736		}
737		return nil
738	}
