740	func pruneV2ArchivedCheckpointRef(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, refName plumbing.ReferenceName, cpID id.CheckpointID) error {
741		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
742		if err != nil {
743			if errors.Is(err, plumbing.ErrReferenceNotFound) {
744				return nil
745			}
746			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
747		}
748	
749		rootTree, err := repo.TreeObject(rootTreeHash)
750		if err != nil {
751			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
752		}
753		if _, err := rootTree.Tree(cpID.Path()); err != nil {
754			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
755		}
756	
757		shardPrefix := string(cpID[:2])
758		shardSuffix := string(cpID[2:])
759		newRoot, err := pruneCheckpointFromRoot(repo, rootTreeHash, shardPrefix, shardSuffix)
760		if err != nil {
761			return fmt.Errorf("failed to remove checkpoint subtree from %s: %w", refName, err)
762		}
763		if newRoot == rootTreeHash {
764			return nil
765		}
766	
767		count, err := v2Store.CountCheckpointsInTree(newRoot)
768		if err != nil {
769			return fmt.Errorf("failed to count checkpoints in pruned %s: %w", refName, err)
770		}
771		if count == 0 {
772			if err := repo.Storer.RemoveReference(refName); err != nil {
773				return fmt.Errorf("failed to remove empty archived v2 generation %s: %w", refName, err)
774			}
775			return nil
776		}
777	
778		newRoot, err = addRecomputedGenerationJSON(v2Store, newRoot)
779		if err != nil {
780			return fmt.Errorf("failed to recompute generation metadata for %s: %w", refName, err)
781		}
782	
783		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
784			fmt.Sprintf("Reset checkpoint before force migration: %s\n", cpID),
785			migrateAuthorName, migrateAuthorEmail)
786		if err != nil {
787			return fmt.Errorf("failed to create v2 prune commit for %s: %w", refName, err)
788		}
789	
790		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
791			return fmt.Errorf("failed to update ref %s: %w", refName, err)
792		}
793		return nil
794	}
