796	func addRecomputedGenerationJSON(v2Store *checkpoint.V2GitStore, treeHash plumbing.Hash) (plumbing.Hash, error) {
797		gen, found, err := v2Store.ComputeGenerationTimestampsFromTrees(treeHash, nil)
798		if err != nil {
799			return plumbing.ZeroHash, fmt.Errorf("compute raw transcript timestamps: %w", err)
800		}
801		if !found {
802			gen, found, err = v2Store.ComputeGenerationCheckpointTimestamps(treeHash)
803			if err != nil {
804				return plumbing.ZeroHash, fmt.Errorf("compute checkpoint timestamps: %w", err)
805			}
806		}
807		if !found {
808			return treeHash, nil
809		}
810	
811		newTreeHash, err := v2Store.AddGenerationJSONToTree(treeHash, gen)
812		if err != nil {
813			return plumbing.ZeroHash, fmt.Errorf("add generation metadata: %w", err)
814		}
815		return newTreeHash, nil
816	}
