818	func pruneCheckpointFromRoot(repo *git.Repository, rootTreeHash plumbing.Hash, shardPrefix, shardSuffix string) (plumbing.Hash, error) {
819		newRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
820			[]string{shardPrefix},
821			nil,
822			checkpoint.UpdateSubtreeOptions{
823				MergeMode:   checkpoint.MergeKeepExisting,
824				DeleteNames: []string{shardSuffix},
825			},
826		)
827		if err != nil {
828			return plumbing.ZeroHash, fmt.Errorf("failed to prune checkpoint from shard: %w", err)
829		}
830		if newRoot == rootTreeHash {
831			return newRoot, nil
832		}
833	
834		newRootTree, err := repo.TreeObject(newRoot)
835		if err != nil {
836			return plumbing.ZeroHash, fmt.Errorf("failed to read pruned root tree: %w", err)
837		}
838		shardTree, err := newRootTree.Tree(shardPrefix)
839		if err != nil {
840			return newRoot, nil //nolint:nilerr // The shard prefix was already absent after pruning.
841		}
842		if len(shardTree.Entries) > 0 {
843			return newRoot, nil
844		}
845	
846		prunedRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
847			nil,
848			nil,
849			checkpoint.UpdateSubtreeOptions{
850				MergeMode:   checkpoint.MergeKeepExisting,
851				DeleteNames: []string{shardPrefix},
852			},
853		)
854		if err != nil {
855			return plumbing.ZeroHash, fmt.Errorf("failed to prune empty shard prefix: %w", err)
856		}
857		return prunedRoot, nil
858	}
