899	func compactTranscriptForStartLine(ctx context.Context, transcript []byte, m checkpoint.CommittedMetadata, startLine int) []byte {
900		if len(transcript) == 0 {
901			return nil
902		}
903		if m.Agent == "" {
904			logging.Warn(ctx, "compact transcript skipped: no agent type in checkpoint metadata",
905				slog.String("checkpoint_id", string(m.CheckpointID)),
906			)
907			return nil
908		}
909	
910		compacted, err := compact.Compact(redact.AlreadyRedacted(transcript), compact.MetadataFields{
911			Agent:      string(m.Agent),
912			CLIVersion: versioninfo.Version,
913			StartLine:  startLine,
914		})
915		if err != nil {
916			logging.Warn(ctx, "compact transcript generation failed during migration",
917				slog.String("checkpoint_id", string(m.CheckpointID)),
918				slog.String("agent", string(m.Agent)),
919				slog.String("error", err.Error()),
920			)
921			return nil
922		}
923		if len(compacted) == 0 {
924			logging.Warn(ctx, "transcript.jsonl generation produced no output",
925				slog.String("checkpoint_id", string(m.CheckpointID)),
926				slog.String("agent", string(m.Agent)),
927				slog.Int("input_bytes", len(transcript)),
928			)
929			return nil
930		}
931		return compacted
932	}
