934	// computeCompactOffset determines the transcript.jsonl line offset for a checkpoint
935	// by comparing a full compact (startLine=0) against the scoped compact. The difference
936	// is the number of compact lines before this checkpoint's data.
937	func computeCompactOffset(ctx context.Context, fullTranscript, fullCompact []byte, m checkpoint.CommittedMetadata) int {
938		startLine := m.GetTranscriptStart()
939		if startLine == 0 || len(fullTranscript) == 0 || m.Agent == "" {
940			return 0
941		}
942	
943		if len(fullCompact) == 0 {
944			return 0
945		}
946	
947		scopedCompact, err := compact.Compact(redact.AlreadyRedacted(fullTranscript), compact.MetadataFields{
948			Agent:      string(m.Agent),
949			CLIVersion: versioninfo.Version,
950			StartLine:  startLine,
951		})
952		if err != nil {
953			logging.Warn(ctx, "compact transcript offset calculation failed during migration",
954				slog.String("checkpoint_id", string(m.CheckpointID)),
955				slog.String("agent", string(m.Agent)),
956				slog.String("error", err.Error()),
957			)
958			return 0
959		}
960		if len(scopedCompact) == 0 {
961			return 0
962		}
963	
964		fullLines := bytes.Count(fullCompact, []byte{'\n'})
965		scopedLines := bytes.Count(scopedCompact, []byte{'\n'})
966		offset := fullLines - scopedLines
967		if offset < 0 {
968			logging.Warn(ctx, "compact transcript offset was negative during migration, defaulting to 0",
969				slog.String("checkpoint_id", string(m.CheckpointID)),
970				slog.Int("full_lines", fullLines),
971				slog.Int("scoped_lines", scopedLines),
972			)
973			return 0
974		}
975		return offset
976	}
