978	func collectTaskMetadataForMigratedFullGeneration(repo *git.Repository, cpID id.CheckpointID, summary *checkpoint.CheckpointSummary, v1ToV2SessionIdx map[int]int) (map[int][]plumbing.Hash, error) {
979		rootTaskV2SessionIdx, attachRootTasks := latestMigratedV2SessionIndex(v1ToV2SessionIdx)
980		return collectTaskMetadataForMigratedFullGenerationWithRootSession(repo, cpID, summary, v1ToV2SessionIdx, rootTaskV2SessionIdx, attachRootTasks)
981	}
982	
983	func collectTaskMetadataForMigratedFullGenerationWithRootSession(
984		repo *git.Repository,
985		cpID id.CheckpointID,
986		summary *checkpoint.CheckpointSummary,
987		v1ToV2SessionIdx map[int]int,
988		rootTaskV2SessionIdx int,
989		attachRootTasks bool,
990	) (map[int][]plumbing.Hash, error) {
991		v1Tree, err := resolveV1CheckpointTree(repo, cpID)
992		if err != nil {
993			return nil, err
994		}
995	
996		taskTrees := make(map[int][]plumbing.Hash)
997	
998		// Legacy v1 layout stores task metadata at checkpoint root: <cp>/tasks/<tool-use-id>/...
999		// Prefer attaching this tree to the latest session in v2.
1000		if rootTasksTree, rootTasksErr := v1Tree.Tree("tasks"); rootTasksErr == nil {
1001			if attachRootTasks {
1002				taskTrees[rootTaskV2SessionIdx] = append(taskTrees[rootTaskV2SessionIdx], rootTasksTree.Hash)
1003			}
1004		}
1005	
1006		for sessionIdx := range len(summary.Sessions) {
1007			sessionDir := strconv.Itoa(sessionIdx)
1008			sessionTree, sessionErr := v1Tree.Tree(sessionDir)
1009			if sessionErr != nil {
1010				continue
1011			}
1012	
1013			tasksTree, tasksErr := sessionTree.Tree("tasks")
1014			if tasksErr != nil {
1015				continue
1016			}
1017	
1018			v2SessionIdx, ok := v1ToV2SessionIdx[sessionIdx]
1019			if !ok {
1020				continue
1021			}
1022			taskTrees[v2SessionIdx] = append(taskTrees[v2SessionIdx], tasksTree.Hash)
1023		}
1024	
1025		return taskTrees, nil
1026	}
1027	
1028	func latestMigratedV2SessionIndex(v1ToV2SessionIdx map[int]int) (int, bool) {
1029		latest := -1
1030		for _, v2SessionIdx := range v1ToV2SessionIdx {
1031			if v2SessionIdx > latest {
1032				latest = v2SessionIdx
1033			}
1034		}
1035		if latest < 0 {
1036			return -1, false
1037		}
1038		return latest, true
1039	}
