1041	func resolveV1CheckpointTree(repo *git.Repository, cpID id.CheckpointID) (*object.Tree, error) {
1042		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1043		ref, err := repo.Reference(refName, true)
1044		if err != nil {
1045			// Try remote tracking branch
1046			remoteRefName := plumbing.NewRemoteReferenceName(migrateRemoteName, paths.MetadataBranchName)
1047			ref, err = repo.Reference(remoteRefName, true)
1048			if err != nil {
1049				return nil, fmt.Errorf("v1 branch not found: %w", err)
1050			}
1051		}
1052	
1053		commit, err := repo.CommitObject(ref.Hash())
1054		if err != nil {
1055			return nil, fmt.Errorf("failed to get v1 commit: %w", err)
1056		}
1057	
1058		rootTree, err := commit.Tree()
1059		if err != nil {
1060			return nil, fmt.Errorf("failed to get v1 tree: %w", err)
1061		}
1062	
1063		cpTree, err := rootTree.Tree(cpID.Path())
1064		if err != nil {
1065			return nil, fmt.Errorf("checkpoint %s not found in v1 tree: %w", cpID, err)
1066		}
1067	
1068		return cpTree, nil
1069	}
1070	
1071	// collectMissingFullCheckpointForPacking returns a migratedFullCheckpoint
1072	// scoped to the sessions that lack /full/* artifacts on this v2 checkpoint,
1073	// reading their content from v1 so the caller can hand it to the same
1074	// generationPacker fresh migrations use. Returns errAlreadyMigrated when
1075	// every session is already packed.
1076	func collectMissingFullCheckpointForPacking(
1077		ctx context.Context,
1078		repo *git.Repository,
1079		v1Store *checkpoint.GitStore,
1080		v2Store *checkpoint.V2GitStore,
1081		info checkpoint.CommittedInfo,
1082		v2Summary *checkpoint.CheckpointSummary,
1083		fullArtifacts checkpoint.FullSessionArtifactsIndex,
1084	) (*migratedFullCheckpoint, error) {
1085		missingSessions, err := collectMissingFullSessionsForPacking(ctx, v2Store, info.CheckpointID, v2Summary, fullArtifacts)
1086		if err != nil {
1087			return nil, err
1088		}
1089		if len(missingSessions) == 0 {
1090			return nil, errAlreadyMigrated
1091		}
1092	
1093		v1Summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
1094		if err != nil {
1095			return nil, fmt.Errorf("failed to read v1 summary while resuming v2 migration: %w", err)
1096		}
1097		if v1Summary == nil {
1098			return nil, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
1099		}
1100	
1101		v1BySessionID, err := collectV1SessionIndexesForPacking(ctx, v1Store, info.CheckpointID, v1Summary, missingSessions)
1102		if err != nil {
1103			return nil, err
1104		}
1105	
1106		fullCheckpoint := &migratedFullCheckpoint{
1107			checkpointID: info.CheckpointID,
1108		}
1109		v1ToV2SessionIdx := make(map[int]int)
1110	
1111		for _, missingSession := range missingSessions {
1112			v1Session, ok, readErr := readV1SessionForMissingFullArtifact(ctx, v1Store, info.CheckpointID, v1Summary, v1BySessionID, missingSession)
1113			if readErr != nil {
1114				return nil, readErr
1115			}
1116			if !ok {
1117				return nil, fmt.Errorf("failed to find v1 session for v2 session %d while resuming migration", missingSession.sessionIndex)
1118			}
1119	
1120			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
1121				sessionIndex: missingSession.sessionIndex,
1122				content:      v1Session.content,
1123			})
1124			v1ToV2SessionIdx[v1Session.sessionIndex] = missingSession.sessionIndex
1125		}
1126	
1127		latestV2SessionIdx := len(v2Summary.Sessions) - 1
1128		taskTrees, taskErr := collectTaskMetadataForMigratedFullGenerationWithRootSession(
1129			repo,
1130			info.CheckpointID,
1131			v1Summary,
1132			v1ToV2SessionIdx,
1133			latestV2SessionIdx,
1134			latestV2SessionIdx >= 0,
1135		)
1136		if taskErr != nil {
1137			return nil, fmt.Errorf("failed to collect task metadata while resuming migration: %w", taskErr)
