1197	func collectV1SessionIndexesForPacking(
1198		ctx context.Context,
1199		v1Store *checkpoint.GitStore,
1200		checkpointID id.CheckpointID,
1201		summary *checkpoint.CheckpointSummary,
1202		missingSessions []missingFullSessionForPacking,
1203	) (map[string][]int, error) {
1204		neededSessionIDs := make(map[string]struct{})
1205		for _, session := range missingSessions {
1206			if session.sessionID != "" {
1207				neededSessionIDs[session.sessionID] = struct{}{}
1208			}
1209		}
1210	
1211		bySessionID := make(map[string][]int)
1212		if len(neededSessionIDs) == 0 {
1213			return bySessionID, nil
1214		}
1215	
1216		for sessionIdx := range len(summary.Sessions) {
1217			metadata, err := v1Store.ReadSessionMetadata(ctx, checkpointID, sessionIdx)
1218			if err != nil {
1219				if ctxErr := ctx.Err(); ctxErr != nil {
1220					return nil, fmt.Errorf("context canceled while reading v1 session metadata: %w", ctxErr)
1221				}
1222				continue
1223			}
1224			if _, ok := neededSessionIDs[metadata.SessionID]; ok {
1225				bySessionID[metadata.SessionID] = append(bySessionID[metadata.SessionID], sessionIdx)
1226			}
1227		}
1228	
1229		return bySessionID, nil
