1232	func readV1SessionForMissingFullArtifact(
1233		ctx context.Context,
1234		v1Store *checkpoint.GitStore,
1235		checkpointID id.CheckpointID,
1236		summary *checkpoint.CheckpointSummary,
1237		bySessionID map[string][]int,
1238		missingSession missingFullSessionForPacking,
1239	) (v1SessionForPacking, bool, error) {
1240		var triedSessionIndexes map[int]struct{}
1241		if missingSession.sessionID != "" {
1242			indexes := bySessionID[missingSession.sessionID]
1243			triedSessionIndexes = make(map[int]struct{}, len(indexes))
1244			for i := len(indexes) - 1; i >= 0; i-- {
1245				sessionIdx := indexes[i]
1246				triedSessionIndexes[sessionIdx] = struct{}{}
1247				session, found, err := readV1SessionForPacking(ctx, v1Store, checkpointID, sessionIdx)
1248				if err != nil || found {
1249					return session, found, err
1250				}
1251			}
1252		}
1253	
1254		if missingSession.sessionIndex >= len(summary.Sessions) {
1255			return v1SessionForPacking{}, false, nil
1256		}
1257		if _, tried := triedSessionIndexes[missingSession.sessionIndex]; tried {
1258			return v1SessionForPacking{}, false, nil
1259		}
1260		return readV1SessionForPacking(ctx, v1Store, checkpointID, missingSession.sessionIndex)
1261	}
