1792	// GetGitAuthorFromRepo retrieves the git user.name and user.email,
1793	// checking both the repository-local config and the global ~/.gitconfig.
1794	func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
1795		// ConfigScoped merges local + global (local wins), matching git's own resolution.
1796		// Requires a ConfigLoader plugin to be registered; cmd/entire/main.go blank-imports
1797		// go-git/v6/x/plugin to register the default Auto loader.
1798		if cfg, err := repo.ConfigScoped(config.GlobalScope); err == nil {
1799			name = cfg.User.Name
1800			email = cfg.User.Email
1801		}
1802	
1803		// If not found in local config, try global config
1804		if name == "" || email == "" {
1805			//nolint:staticcheck // the v6 is not yet released, revisit once it is.
1806			globalCfg, err := config.LoadConfig(config.GlobalScope)
1807			if err == nil {
1808				if name == "" {
1809					name = globalCfg.User.Name
1810				}
1811				if email == "" {
1812					email = globalCfg.User.Email
1813				}
1814			}
1815		}
1816	
1817		// Provide sensible defaults if git user is not configured
1818		if name == "" {
1819			name = "Unknown"
1820		}
1821		if email == "" {
1822			email = "unknown@local"
1823		}
1824	
1825		return name, email
1826	}
