97	// V2MainFetchTmpRef is the staging ref for fetches that target V2MainRefName.
98	// Shared between the cli package's origin-based fetches and the strategy
99	// package's checkpoint_remote URL-based fetch — those code paths never run
100	// concurrently (they are sequenced in explain and resume), so reusing one
101	// staging ref is safe and avoids divergent conventions.
102	const V2MainFetchTmpRef = FetchTmpRefPrefix + "v2-main"
