104	// PromoteTmpRefSafely reads tmpRefName (the ref a fetch just landed into),
105	// advances destRefName to its hash via SafelyAdvanceLocalRef, then removes
106	// the tmp ref. The cleanup is deferred so the tmp ref is reaped even when
107	// the advance fails.
108	//
109	// label is a short human-readable name used in error messages (e.g.
110	// "v2 /main", "entire/checkpoints/v1"). Typical use:
111	//
112	//	// fetch with refspec "+<src>:<V2MainFetchTmpRef>"
113	//	return PromoteTmpRefSafely(ctx, V2MainFetchTmpRef, paths.V2MainRefName, "v2 /main")
114	func PromoteTmpRefSafely(ctx context.Context, tmpRefName, destRefName plumbing.ReferenceName, label string) error {
115		repo, err := OpenRepository(ctx)
116		if err != nil {
117			return fmt.Errorf("failed to open repository for %s promote: %w", label, err)
118		}
119		defer func() { _ = repo.Storer.RemoveReference(tmpRefName) }() //nolint:errcheck // cleanup is best-effort
120	
121		tmpRef, err := repo.Reference(tmpRefName, true)
122		if err != nil {
123			return fmt.Errorf("%s not found after fetch (tmp ref %s missing): %w", label, tmpRefName, err)
124		}
125		if err := SafelyAdvanceLocalRef(ctx, repo, destRefName, tmpRef.Hash()); err != nil {
126			return fmt.Errorf("failed to advance local %s: %w", label, err)
127		}
128		return nil
129	}
