131	// SafelyAdvanceLocalRef updates localRefName to point at targetHash, except
132	// when the existing local ref is already at or ahead of targetHash. In that
133	// case it leaves the local ref unchanged to avoid rewinding locally-ahead
134	// work. Otherwise (local missing, behind, or diverged) it updates the ref to
135	// targetHash.
136	//
137	// The ancestry check walks from the local ref (which has full history), so
138	// callers that fetched with --depth=1 do not break the check.
139	func SafelyAdvanceLocalRef(ctx context.Context, repo *git.Repository, localRefName plumbing.ReferenceName, targetHash plumbing.Hash) error {
140		currentLocal, localErr := repo.Reference(localRefName, true)
141		if localErr == nil {
142			if currentLocal.Hash() == targetHash {
143				return nil
144			}
145			if IsAncestorOf(ctx, repo, targetHash, currentLocal.Hash()) {
146				return nil
147			}
148		}
149	
150		newRef := plumbing.NewHashReference(localRefName, targetHash)
151		if err := repo.Storer.SetReference(newRef); err != nil {
152			return fmt.Errorf("failed to update local ref %s: %w", localRefName, err)
153		}
154		return nil
155	}
