157	// IsAncestorOf checks if commit is an ancestor of (or equal to) target.
158	// Returns true if target can reach commit by following parent links.
159	// Limits search to MaxCommitTraversalDepth commits to avoid excessive traversal.
160	func IsAncestorOf(ctx context.Context, repo *git.Repository, commit, target plumbing.Hash) bool {
161		if commit == target {
162			return true
163		}
164	
165		iter, err := repo.Log(&git.LogOptions{From: target})
166		if err != nil {
167			return false
168		}
169		defer iter.Close()
170	
171		found := false
172		count := 0
173		_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best-effort search, errors are non-fatal
174			if err := ctx.Err(); err != nil {
175				return err //nolint:wrapcheck // Propagating context cancellation
176			}
177			count++
178			if count > MaxCommitTraversalDepth {
179				return errStop
180			}
181			if c.Hash == commit {
182				found = true
183				return errStop
184			}
185			return nil
186		})
187	
188		return found
189	}
