191	// ListCheckpoints returns all checkpoints from the entire/checkpoints/v1 branch.
192	// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
193	func ListCheckpoints(ctx context.Context) ([]CheckpointInfo, error) {
194		repo, err := OpenRepository(ctx)
195		if err != nil {
196			return nil, fmt.Errorf("failed to open git repository: %w", err)
197		}
198	
199		// Warn (once per process) if metadata branches are disconnected
200		WarnIfMetadataDisconnected()
201	
202		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
203		ref, err := repo.Reference(refName, true)
204		if err != nil {
205			//nolint:nilerr // No sessions branch yet is expected, return empty list
206			return []CheckpointInfo{}, nil
207		}
208	
209		commit, err := repo.CommitObject(ref.Hash())
210		if err != nil {
211			return nil, fmt.Errorf("failed to get commit object: %w", err)
212		}
213	
214		tree, err := commit.Tree()
215		if err != nil {
216			return nil, fmt.Errorf("failed to get commit tree: %w", err)
217		}
218	
219		var checkpoints []CheckpointInfo
220	
221		// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
222		// The tree has 2-character directories (hex buckets)
223		for _, bucketEntry := range tree.Entries {
224			if bucketEntry.Mode != filemode.Dir {
225				continue
226			}
227			// Bucket should be 2 hex chars
228			if len(bucketEntry.Name) != 2 {
229				continue
230			}
231	
232			bucketTree, treeErr := repo.TreeObject(bucketEntry.Hash)
233			if treeErr != nil {
234				continue
235			}
236	
237			// Each entry in the bucket is the remaining part of the checkpoint ID
238			for _, checkpointEntry := range bucketTree.Entries {
239				if checkpointEntry.Mode != filemode.Dir {
240					continue
241				}
242	
243				checkpointTree, cpTreeErr := repo.TreeObject(checkpointEntry.Hash)
244				if cpTreeErr != nil {
245					continue
246				}
247	
248				// Reconstruct checkpoint ID: <bucket><remaining>
249				checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
250				checkpointID, cpErr := id.NewCheckpointID(checkpointIDStr)
251				if cpErr != nil {
252					// Skip invalid checkpoint IDs
253					continue
254				}
255	
256				info := CheckpointInfo{
257					CheckpointID: checkpointID,
258				}
259	
260				// Get details from metadata file (CheckpointSummary format)
261				if summary, ok := decodeSummaryLiteFromTree(checkpointTree); ok {
262					info.CheckpointsCount = summary.CheckpointsCount
263					info.FilesTouched = summary.FilesTouched
264					info.SessionCount = len(summary.Sessions)
265	
266					// Read session-level metadata for Agent, SessionID, CreatedAt, SessionIDs
267					for i, sessionPaths := range summary.Sessions {
268						if sessionPaths.Metadata == "" {
269							continue
270						}
271						// SessionFilePaths contains absolute paths with leading "/"
272						// Strip the leading "/" for tree.File() which expects paths without leading slash
273						sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
274						sessionMeta, sErr := decodeSessionMetadataLite(tree, sessionMetadataPath)
275						if sErr != nil {
276							continue
277						}
278						info.SessionIDs = append(info.SessionIDs, sessionMeta.SessionID)
279						// Use first session's metadata for Agent, SessionID, CreatedAt
280						if i == 0 {
281							info.Agent = sessionMeta.Agent
282							info.SessionID = sessionMeta.SessionID
283							info.CreatedAt = sessionMeta.CreatedAt
