17	// CheckpointTokenEnvVar is the environment variable for providing an access token
18	// used to authenticate git push/fetch operations for checkpoint branches.
19	// The token is injected as an HTTP Basic Authorization header per RFC 7617:
20	// the credentials string "x-access-token:<token>" is base64-encoded and sent as
21	// "Authorization: Basic <base64>". This matches GitHub's token auth for Git HTTPS.
22	// SSH remotes ignore the token (with a warning).
23	const CheckpointTokenEnvVar = "ENTIRE_CHECKPOINT_TOKEN"
