27	// FetchOptions configures a git fetch operation.
28	type FetchOptions struct {
29		Remote    string   // remote name or URL (required)
30		RefSpecs  []string // one or more refspecs / object hashes
31		Shallow   bool     // adds --depth=1
32		NoTags    bool     // adds --no-tags
33		NoFilter  bool     // when true, skips --filter=blob:none even if filtered fetches are enabled
34		Dir       string   // working directory (empty = CWD)
35		ExtraArgs []string // additional flags before remote (e.g., "--no-write-fetch-head")
36	}
