38	// Fetch runs git fetch with checkpoint token injection and optional
39	// filtered fetches (--filter=blob:none when settings enable it).
40	// GIT_TERMINAL_PROMPT=0 is always set.
41	//
42	// Callers that pass a remote name (e.g., "origin") and want filtered fetches to
43	// resolve the name to a URL (to avoid persisting promisor settings) should call
44	// ResolveFetchTarget first and pass the resolved target as opts.Remote.
45	func Fetch(ctx context.Context, opts FetchOptions) ([]byte, error) {
46		args := []string{"fetch"}
47		if opts.NoTags {
48			args = append(args, "--no-tags")
49		}
50		if opts.Shallow {
51			args = append(args, "--depth=1")
52		}
53		args = append(args, opts.ExtraArgs...)
54		if !opts.NoFilter && settings.IsFilteredFetchesEnabled(ctx) {
55			args = append(args, "--filter=blob:none")
56		}
57		args = append(args, opts.Remote)
58		args = append(args, opts.RefSpecs...)
59	
60		cmd := newCommand(ctx, args...)
61		if opts.Dir != "" {
62			cmd.Dir = opts.Dir
63		}
64		disableTerminalPrompt(cmd)
65		out, err := cmd.CombinedOutput()
66		if err != nil {
67			return out, fmt.Errorf("git fetch: %w", err)
68		}
69		return out, nil
70	}
