72	// FetchBlobs fetches specific objects (typically blobs) by hash from a remote.
73	// Uses `git fetch-pack` rather than `git fetch` because the high-level
74	// porcelain enforces partial-clone integrity checks that reject blob-only
75	// responses with "did not send all necessary objects". Plumbing skips those
76	// checks — it just downloads the requested objects into .git/objects/pack
77	// and exits — which is exactly what we want when grabbing individual blobs
78	// by SHA. Works against GitHub for any reachable object, including blobs.
79	//
80	// The remote should be a URL (not a remote name) to avoid persisting promisor
81	// settings onto the named remote. Use FetchURL to obtain the URL.
82	func FetchBlobs(ctx context.Context, remote string, hashes []string) error {
83		args := []string{"fetch-pack", remote}
84		args = append(args, hashes...)
85	
86		cmd := newCommand(ctx, args...)
87		disableTerminalPrompt(cmd)
88		output, err := cmd.CombinedOutput()
89		if err != nil {
90			redactedURL := RedactURL(remote)
91			msg := strings.TrimSpace(strings.ReplaceAll(string(output), remote, redactedURL))
92			if msg != "" {
93				return fmt.Errorf("git fetch-pack from %s: %s: %w", redactedURL, msg, err)
94			}
95			return fmt.Errorf("git fetch-pack from %s: %w", redactedURL, err)
96		}
97		return nil
98	}
