191	// newCommand creates an exec.Cmd for a git operation that may need
192	// checkpoint token authentication. If ENTIRE_CHECKPOINT_TOKEN is set:
193	//   - if the target in args is (or resolves to) an SSH remote, the target is
194	//     rewritten in the args to the equivalent HTTPS URL so git uses HTTP
195	//     transport and our injected Authorization header applies;
196	//   - a Basic auth token is then injected via GIT_CONFIG_COUNT/GIT_CONFIG_KEY_*/
197	//     GIT_CONFIG_VALUE_* environment variables.
198	//
199	// If rewriting fails (unparseable URL, missing owner/repo) the command runs
200	// unmodified and a one-shot warning is printed.
201	// For empty/unset tokens, the command is returned unmodified.
202	//
203	// The remote is extracted from args by skipping the git subcommand and any flags
204	// (arguments starting with "-"). For example, in
205	// ["push", "--no-verify", "origin", "main"], the remote is "origin".
206	func newCommand(ctx context.Context, args ...string) *exec.Cmd {
207		token := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar))
208	
209		mkCmd := func(finalArgs []string) *exec.Cmd {
210			c := exec.CommandContext(ctx, "git", finalArgs...)
211			c.Stdin = nil // Disconnect stdin to prevent hanging in hook context
212			return c
213		}
214	
215		if token == "" {
216			return mkCmd(args)
217		}
218	
219		if !isValidToken(token) {
220			fmt.Fprintf(os.Stderr, "[entire] Warning: %s contains invalid characters (CR, LF, or other control chars) — token ignored\n", CheckpointTokenEnvVar)
221			return mkCmd(args)
222		}
223	
224		target := extractRemoteFromArgs(args)
225		if target == "" {
226			return mkCmd(args)
227		}
228	
229		newTarget, protocol := resolveTargetForTokenAuth(ctx, target)
230		if newTarget != target {
231			args = replaceFirstPositional(args, newTarget)
232		}
233	
234		cmd := mkCmd(args)
235	
236		switch protocol {
237		case ProtocolSSH:
238			sshTokenWarningOnce.Do(func() {
239				fmt.Fprintf(os.Stderr, "[entire] Warning: %s is set but remote uses SSH — token ignored for SSH remotes\n", CheckpointTokenEnvVar)
240			})
241			return cmd
242		case ProtocolHTTPS:
243			cmd.Env = appendCheckpointTokenEnv(os.Environ(), token)
244			return cmd
245		default:
246			// Unknown protocol (e.g., local path, or resolution failed) — don't inject
247			return cmd
248		}
249	}
250	
251	// resolveTargetForTokenAuth resolves a git target (remote name or URL) to its
252	// effective protocol, rewriting SSH targets to the equivalent HTTPS URL so
253	// token-based auth can be applied. Returns the (possibly rewritten) target and
254	// its final protocol. Protocol is "" when resolution fails (local path,
255	// nonexistent remote, unparseable URL).
256	//
257	// This is only meaningful when ENTIRE_CHECKPOINT_TOKEN is set; callers gate on
258	// that themselves.
