289	// argument after args[0] (the git subcommand) replaced by newTarget. Callers
290	// use this to rewrite a remote name/URL after resolution without mutating the
291	// original slice.
292	func replaceFirstPositional(args []string, newTarget string) []string {
293		out := make([]string, len(args))
294		copy(out, args)
295		for i := 1; i < len(out); i++ {
296			if !strings.HasPrefix(out[i], "-") {
297				out[i] = newTarget
