305	// It skips the subcommand (first arg) and any flags (args starting with "-"),
306	// returning the first positional argument, which is the remote for push/fetch/ls-remote.
307	func extractRemoteFromArgs(args []string) string {
308		if len(args) < 2 {
309			return ""
310		}
311		// Skip subcommand (e.g., "push", "fetch", "ls-remote").
312		for _, arg := range args[1:] {
313			if !strings.HasPrefix(arg, "-") {
314				return arg
315			}
316		}
