321	// an Authorization header into git HTTP requests. The token is sent as a Basic
322	// credential with the format "x-access-token:<token>" (base64-encoded), which
323	// is compatible with GitHub's token authentication.
324	//
325	// Existing GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries are preserved; the new
326	// http.extraHeader entry is appended at the next free index and
327	// GIT_CONFIG_COUNT is updated accordingly. This keeps caller-injected git
328	// config (e.g., safe.directory, custom CA settings) intact.
329	func appendCheckpointTokenEnv(baseEnv []string, token string) []string {
330		existingCount := 0
331		for _, e := range baseEnv {
332			rest, ok := strings.CutPrefix(e, "GIT_CONFIG_COUNT=")
333			if !ok {
334				continue
335			}
336			if n, err := strconv.Atoi(rest); err == nil && n > 0 {
337				existingCount = n
338			}
339		}
340	
341		// Strip the old GIT_CONFIG_COUNT entry (we'll emit a new one) but keep
342		// GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries in place.
343		filtered := make([]string, 0, len(baseEnv)+3)
344		for _, e := range baseEnv {
345			if strings.HasPrefix(e, "GIT_CONFIG_COUNT=") {
346				continue
347			}
348			filtered = append(filtered, e)
349		}
