351		idx := existingCount
352		encoded := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + token))
353		return append(filtered,
354			fmt.Sprintf("GIT_CONFIG_COUNT=%d", existingCount+1),
355			fmt.Sprintf("GIT_CONFIG_KEY_%d=http.extraHeader", idx),
356			fmt.Sprintf("GIT_CONFIG_VALUE_%d=Authorization: Basic %s", idx, encoded),
357		)
358	}
