390		}
391		if !enabled || pushTarget == "" {
392			return target, nil
393		}
394		return pushTarget, nil
395	}
396	
397	func isLocalPath(target string) bool {
398		return filepath.IsAbs(target) || strings.HasPrefix(target, "./") || strings.HasPrefix(target, "../")
399	}
