401	// disableTerminalPrompt sets GIT_TERMINAL_PROMPT=0 on the command,
402	// initializing cmd.Env from os.Environ() if nil.
403	func disableTerminalPrompt(cmd *exec.Cmd) {
404		if cmd.Env == nil {
405			cmd.Env = os.Environ()
406		}
407		cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
